152	STATIC int npu_get_resource_info(struct npu_card_total_info *card_info, int device_id)
153	{
154	    int proc_index, ret;
155	#ifdef NPU_SMI_V2
156	    ret = dcmiv2_get_device_proc_mem_info(card_info->card_id,
157	        card_info->chip_proc_info[device_id], &card_info->proc_nums[device_id]);
158	    if ((ret != DCMI_OK) && (ret != DCMI_ERR_CODE_NOT_SUPPORT)) {
159	        gplog(LOG_ERR, "dcmiv2_get_device_proc_mem_info failed. err is %d", ret);
160	        return dcmi_to_npu_error_code(ret);
161	    }
162	#else
163	    ret = dcmi_get_device_resource_info(card_info->card_id, device_id,
164	        card_info->chip_proc_info[device_id], &card_info->proc_nums[device_id]);
165	    if ((ret != DCMI_OK) && (ret != DCMI_ERR_CODE_NOT_SUPPORT)) {
166	        gplog(LOG_ERR, "dcmi_get_device_resource_info failed. err is %d", ret);
167	        return dcmi_to_npu_error_code(ret);
168	    }
169	#endif
170	    for (proc_index = 0; proc_index < card_info->proc_nums[device_id]; proc_index++) {
171	        ret = get_pid_name(card_info->chip_proc_info[device_id][proc_index].proc_id,
172	            card_info->chip_proc_name[device_id][proc_index], MAX_PROCESS_NAME_LEN);
173	        if (ret != NPU_OK) {
174	            gplog(LOG_ERR, "get_pid_name failed. err is %d", ret);
175	        }
176	    }
177	
178	    return ret;
179	}
