222	STATIC int query_card_chip_total_info(struct npu_card_total_info *card_info)
223	{
224	    int chip_index, ret;
225	    enum dcmi_unit_type device_type = INVALID_TYPE;
226	
227	    for (chip_index = 0; chip_index < card_info->chip_count; chip_index++) {
228	        ret = dcmiv2_get_device_type(card_info->card_id, &device_type);
229	        if ((ret != DCMI_OK) && (ret != DCMI_ERR_CODE_NOT_SUPPORT)) {
230	            printf("Failed to get device type.\n");
231	            return NPU_ERR_CODE_DCMI_FUN_FAIL;
232	        }
233	        ret = dcmiv2_get_device_health(card_info->card_id, &card_info->chip_health[chip_index]);
234	        if (ret != DCMI_OK) {
235	            gplog(LOG_ERR, "dcmiv2_get_device_health failed. err is %d", ret);
236	        }
237	
238	        ret = get_chip_info_v2_as_old(card_info->card_id, &card_info->chip_info[chip_index]);
239	        if (ret != DCMI_OK) {
240	            gplog(LOG_ERR, "get_chip_info_v2_as_old failed. err is %d", ret);
241	        }
242	
243	        ret = dcmiv2_check_device_heartbeat_state(card_info->card_id);
244	        if (ret != DCMI_OK) {
245	            gplog(LOG_ERR, "Device heartbeat abnormal, skip query info, (card_id=%d, ret=%d)", card_info->card_id, ret);
246	            continue;
247	        }
248	
249	        if (!dcmi_mainboard_is_a900_a5_ub(g_mainboard_info.mainboard_id)) {
250	            ret = dcmiv2_get_device_pcie_info(card_info->card_id, &card_info->device_pcie_info[chip_index]);
251	            if (ret != DCMI_OK && ret != DCMI_ERR_CODE_NOT_SUPPORT) {
252	                gplog(LOG_ERR, "dcmiv2_get_device_pcie_info failed. err is %d", ret);
253	            }
254	            card_info->is_has_pcie = (ret == DCMI_OK);
255	        }
256	        ret = npu_get_chip_common_info(card_info->card_id, chip_index, &card_info->chip_common_info[chip_index]);
257	        if ((ret != NPU_OK) && (ret != NPU_ERR_CODE_NOT_SUPPORT)) {
258	            gplog(LOG_ERR, "get card %d device %d common info failed. err is %d", card_info->card_id, chip_index, ret);
259	        }
260	        if (check_result_for_dcmi_get_hbm_info()) {
261	            ret = dcmiv2_get_device_hbm_info(card_info->card_id, &card_info->chip_hbm_info[chip_index]);
262	            if ((ret != DCMI_OK) && (ret != DCMI_ERR_CODE_NOT_SUPPORT)) {
263	                gplog(LOG_ERR, "dcmiv2_get_device_hbm_info failed. err is %d", ret);
264	            }
265	        }
266	
267	        ret = npu_get_resource_info(card_info, chip_index);
268	        if ((ret != DCMI_OK) && (ret != DCMI_ERR_CODE_NOT_SUPPORT)) {
269	            gplog(LOG_ERR, "npu_get_resource_info failed. err is %d", ret);
270	        }
271	    }
272	    return NPU_OK;
273	}
