418	STATIC int query_total_info(struct npu_smi_operate_info *operate_info)
419	{
420	    int ret;
421	    int card_id_list[MAX_CARD_NUM] = {0};
422	    struct npu_total_info *npu_total_info = NULL;
423	    enum npu_chip_type chip_type = npu_get_chip_type();
424	
425	    npu_total_info = (struct npu_total_info *)malloc(sizeof(struct npu_total_info));
426	    if (npu_total_info == NULL) {
427	        printf("Failed to alloc memory.\n");
428	        return NPU_ERR_CODE_MEM_OPERATE_FAIL;
429	    }
430	
431	    ret = memset_s(npu_total_info, sizeof(struct npu_total_info), 0, sizeof(struct npu_total_info));
432	    if (ret != 0) {
433	        gplog(LOG_ERR, "memset_s failed. err is %d", ret);
434	    }
435	
436	    ret = get_card_list_internal(card_id_list, &npu_total_info->card_count, MAX_CARD_NUM);
437	    if (ret != NPU_OK) {
438	        free(npu_total_info);
439	        return ret;
440	    }
441	
442	    ret = query_card_total_info(npu_total_info, card_id_list, npu_total_info->card_count);
443	    if (ret != NPU_OK) {
444	        printf("Failed to query card total info.\n");
445	        free(npu_total_info);
446	        return ret;
447	    }
448	
449	    ret = get_driver_version_internal(npu_total_info->software_version,
450	                                      sizeof(npu_total_info->software_version));
451	    if (ret != NPU_OK) {
452	        free(npu_total_info);
453	        return ret;
454	    }
455	
456	    if (chip_type == NPU_CHIP_910 || chip_type == NPU_CHIP_910B ||
457	        chip_type == NPU_CHIP_910_93 || chip_type == NPU_CHIP_950) {
458	        print_total_info_with_HBM(npu_total_info);
459	    } else {
460	        print_total_info(npu_total_info);
461	    }
462	    free(npu_total_info);
463	    return NPU_OK;
464	}
