799	STATIC int topo_read_line_info_from_file(const char *cfg_file_path, char *content)
800	{
801	    FILE *fp = NULL;
802	    int ret = 0;
803	    char file_string[NPU_MAX_LENTH] = {0};
804	    char real_conf_path[PATH_MAX + 1] = {0};
805	
806	    if (realpath(cfg_file_path, real_conf_path) == NULL) {
807	        gplog(LOG_ERR, "node name invalid.\n");
808	        return NPU_ERR_CODE_INVALID_PARAMETER;
809	    }
810	
811	    fp = fopen(real_conf_path, "r");
812	    if (fp == NULL) {
813	        gplog(LOG_ERR, "file open failed. errno is %d\n", errno);
814	        return NPU_ERR_CODE_FILE_OPERATE_FAIL;
815	    }
816	
817	    if (fgets(file_string, sizeof(file_string), fp) == NULL) {
818	        (void)fclose(fp);
819	        fp = NULL;
820	        return NPU_ERR_CODE_FILE_OPERATE_FAIL;
821	    }
822	
823	    int len = strlen(file_string);
824	    if ((len > 0) && (file_string[len - 1] == '\n')) {
825	        file_string[len - 1] = 0;
826	    }
827	
828	    ret = snprintf_s(content, TOPO_INFO_MAX_LENTH, TOPO_INFO_MAX_LENTH - 1, "%s", file_string);
829	    if (ret <= 0) {
830	        gplog(LOG_ERR, "failed to snprintf_s. ret is %d\n", ret);
831	        (void)fclose(fp);
832	        fp = NULL;
833	        return NPU_ERR_CODE_SECURE_FUN_FAIL;
834	    }
835	
836	    (void)fclose(fp);
837	    fp = NULL;
838	    return NPU_OK;
839	}
