882	STATIC int topo_get_config_bytes(unsigned char *config, int offset, int len, unsigned int *output)
883	{
884	    int i;
885	    *output = 0;
886	
887	    if (offset + len >= TOPO_PCIE_CONFIG_SPACE_LEN || (unsigned int)len > sizeof(int)) {
888	        gplog(LOG_ERR, "offset is out of range. offset is %d, len is %d", offset, len);
889	        return NPU_ERR_CODE_INVALID_PARAMETER;
890	    }
891	
892	    for (i = 0; i < len; i++) {
893	        *output <<= BIT_OPERATION_ONE_BYTE;
894	        *output += config[offset + len - i - 1];
895	    }
896	
897	    return NPU_OK;
898	}
