900	STATIC int topo_get_pcie_cfg_info_by_pcie_id(struct topo_pcie_id *pcie_id, struct topo_pcie_cfg_info *config_info)
901	{
902	    int ret;
903	    unsigned char config[TOPO_PCIE_CONFIG_SPACE_LEN] = {0};
904	    unsigned char pci_cap_offset;
905	    unsigned int lnk_cap = 0;
906	    unsigned int lnk_sta = 0;
907	
908	    ret = topo_read_pcie_config_data(pcie_id, config, TOPO_PCIE_CONFIG_SPACE_LEN);
909	    if (ret != NPU_OK) {
910	        gplog(LOG_ERR, "failed to topo_read_pcie_config_data. ret is %d", ret);
911	        return ret;
912	    }
913	
914	    ret = topo_get_config_bytes(config, TOPO_PCI_CLASS_CODE, DEV_CLASS_LEN, &config_info->dev_class);
915	    if (ret != NPU_OK) {
916	        gplog(LOG_ERR, "failed to topo_get_config_bytes. dev_class is %u, ret is %d", config_info->dev_class, ret);
917	        return ret;
918	    }
919	
920	    config_info->primary_bus = (unsigned int)config[TOPO_PCI_PRIMARY_BUS];
921	    config_info->secondary_bus = (unsigned int)config[TOPO_PCI_SECONDARY_BUS];
922	    pci_cap_offset = config[TOPO_PCI_CAPABILITY_LIST];
923	
924	    ret = topo_get_config_bytes(config, pci_cap_offset + TOPO_PCIE_LNKCAP, LNK_CAP_LEN, &lnk_cap);
925	    if (ret != NPU_OK) {
926	        gplog(LOG_ERR, "failed to topo_get_config_bytes. lnk_cap is %u, ret is %d", lnk_cap, ret);
927	        return ret;
928	    }
929	
930	    config_info->cap_speed = lnk_cap & TOPO_PCIE_MASK_LNKCAP_SPEED;
931	    config_info->cap_width = (lnk_cap & TOPO_PCIE_MASK_LNKCAP_WIDTH) >> BIT_OPERATION_CAP_WIDTH;
932	
933	    ret = topo_get_config_bytes(config, pci_cap_offset + TOPO_PCIE_LNKSTA, LNK_STA_LEN, &lnk_sta);
934	    if (ret != NPU_OK) {
935	        gplog(LOG_ERR, "failed to topo_get_config_bytes. lnk_sta is %u, ret is %d", lnk_sta, ret);
936	        return ret;
937	    }
938	
939	    config_info->sta_speed = lnk_sta & TOPO_PCIE_MASK_LNKSTA_SPEED;
940	    config_info->sta_width = (lnk_sta & TOPO_PCIE_MASK_LNKSTA_WIDTH) >> BIT_OPERATION_STA_WIDTH;
941	
942	    return NPU_OK;
943	}
