1011	STATIC int topo_check_dbf_name(char *dbf_name, bool *is_match)
1012	{
1013	    int ret;
1014	    regex_t regex;
1015	
1016	    ret = regcomp(&regex, "([0-9a-f]{4}):([0-9a-f]{2}):([0-9a-f]{2})\\.([0-f]{1})", REG_EXTENDED | REG_NOSUB);
1017	    if (ret != 0) {
1018	        gplog(LOG_ERR, "regcomp failed. ret is %d", ret);
1019	        return NPU_ERR_CODE_INVALID_PARAMETER;
1020	    }
1021	
1022	    ret = regexec(&regex, dbf_name, 0, NULL, 0);
1023	    *is_match = (ret != REG_NOERROR) ? false : true;
1024	    regfree(&regex);
1025	
1026	    return NPU_OK;
1027	}
