1029	STATIC int topo_get_list_dir(char *dir_name, char pcie_dir_list[PCIE_NUM_MAX][PCIE_NAME_LENTH])
1030	{
1031	    int ret = 0;
1032	    int i = 0;
1033	    bool is_match = false;
1034	    struct dirent *ptr = NULL;
1035	
1036	    DIR *dir = opendir(dir_name);
1037	    if (dir == NULL) {
1038	        gplog(LOG_ERR, "opendir failed. dir_name is %s", dir_name);
1039	        return NPU_ERR_CODE_FILE_OPERATE_FAIL;
1040	    }
1041	
1042	    while ((ptr = readdir(dir)) != NULL && (i < PCIE_NUM_MAX)) {
1043	        ret = topo_check_dbf_name(ptr->d_name, &is_match);
1044	        if (ret != NPU_OK || !is_match) {
1045	            continue;
1046	        }
1047	
1048	        ret = strcpy_s(pcie_dir_list[i], PCIE_NAME_LENTH, ptr->d_name);
1049	        if (ret < 0) {
1050	            gplog(LOG_ERR, "strcpy_s failed. d_name is %s", ptr->d_name);
1051	            closedir(dir);
1052	            dir = NULL;
1053	            return NPU_ERR_CODE_SECURE_FUN_FAIL;
1054	        }
1055	        i++;
1056	    }
1057	    closedir(dir);
1058	    dir = NULL;
1059	
1060	    return NPU_OK;
1061	}
