1069	        gplog(LOG_ERR, "topo_check_dbf_name failed. dbf_name is %s, ret is %d", dbf_name, ret);
1070	    }
1071	
1072	    ret = sscanf_s(dbf_name, "%04x:%02x:%02x.%1u",
1073	        &pcie_dev_info->pcie_id.domain, &pcie_dev_info->pcie_id.bdf_busid,
1074	        &pcie_dev_info->pcie_id.bdf_deviceid, &pcie_dev_info->pcie_id.bdf_funcid);
