1101	/* 读取系统中的所有pcie设备信息，然后保存起来 */
1102	STATIC int topo_pcie_init(void)
1103	{
1104	    int ret;
1105	    int i;
1106	    char pcie_dir_list[PCIE_NUM_MAX][PCIE_NAME_LENTH] = {0};
1107	    g_pcie_dev_info_list.prev_pcie_info = &g_pcie_dev_info_list;
1108	    g_pcie_dev_info_list.next_pcie_info = &g_pcie_dev_info_list;
1109	
1110	    ret = topo_get_list_dir(SYS_BUS_PCI_DEVICE_PATH, pcie_dir_list);
1111	    if (ret != NPU_OK) {
1112	        return ret;
1113	    }
1114	
1115	    for (i = 0; (i < PCIE_NUM_MAX) && (pcie_dir_list[i][0] != 0); i++) {
1116	        struct topo_pcie_info pcie_dev_info = {0};
1117	
1118	        ret = topo_get_pcie_dev_info_from_dbf(pcie_dir_list[i], &pcie_dev_info);
1119	        if (ret != NPU_OK) {
1120	            gplog(LOG_ERR, "topo_get_pcie_dev_info_from_dbf failed. ret is %d", ret);
1121	            continue;
1122	        }
1123	
1124	        if ((pcie_dev_info.config.dev_class & TOPO_PCI_CLASS_CODE_MASK) != TOPO_PCI_BASE_CLASS_BRIDGE) {
1125	            continue;
1126	        }
1127	
1128	        struct topo_pcie_info *p_pcie_dev_info = (struct topo_pcie_info *)malloc(sizeof(struct topo_pcie_info));
1129	        if (p_pcie_dev_info == NULL) {
1130	            gplog(LOG_ERR, "alloc memory failed.");
1131	            return NPU_ERR_CODE_MEM_OPERATE_FAIL;
1132	        }
1133	
1134	        ret = memset_s(p_pcie_dev_info, sizeof(struct topo_pcie_info), 0, sizeof(struct topo_pcie_info));
1135	        if (ret != NPU_OK) {
1136	            gplog(LOG_ERR, "memset_s failed. ret is %d", ret);
1137	        }
1138	
1139	        ret = memcpy_s(p_pcie_dev_info, sizeof(struct topo_pcie_info), &pcie_dev_info, sizeof(struct topo_pcie_info));
1140	        if (ret != NPU_OK) {
1141	            gplog(LOG_ERR, "memcpy_s failed. ret is %d", ret);
1142	        }
1143	        // 构造bus->pcie的映射关系
1144	        p_pcie_dev_info->prev_pcie_info = g_pcie_dev_info_list.prev_pcie_info;
1145	        p_pcie_dev_info->next_pcie_info = &g_pcie_dev_info_list;
1146	        g_pcie_dev_info_list.prev_pcie_info->next_pcie_info = p_pcie_dev_info;
1147	        g_pcie_dev_info_list.prev_pcie_info = p_pcie_dev_info;
1148	    }
1149	
1150	    return NPU_OK;
1151	}
