1153	/* 释放topo_pcie_init中申请的内存 */
1154	STATIC void topo_pcie_free(void)
1155	{
1156	    struct topo_pcie_info *tmp_pcie_dev_info = NULL;
1157	    struct topo_pcie_info *p_pcie_dev_info = g_pcie_dev_info_list.next_pcie_info;
1158	
1159	    while (p_pcie_dev_info != &g_pcie_dev_info_list) {
1160	        tmp_pcie_dev_info = p_pcie_dev_info;
1161	        p_pcie_dev_info = tmp_pcie_dev_info->next_pcie_info;
1162	
1163	        if (tmp_pcie_dev_info != NULL) {
1164	            tmp_pcie_dev_info->prev_pcie_info->next_pcie_info = tmp_pcie_dev_info->next_pcie_info;
1165	            tmp_pcie_dev_info->next_pcie_info->prev_pcie_info = tmp_pcie_dev_info->prev_pcie_info;
1166	            free(tmp_pcie_dev_info);
1167	            tmp_pcie_dev_info = NULL;
1168	        }
1169	    }
1170	}
