1194	STATIC int topo_get_full_pcie_chain(struct topo_pcie_info *pcie_dev_info_chain)
1195	{
1196	    unsigned int loop;
1197	    unsigned int max_loop = 0xffff;
1198	    unsigned int primary_bus = 0;
1199	    struct topo_pcie_info *tmp_pcie_dev_info = NULL;
1200	
1201	    for (loop = 0; loop < max_loop; loop++) {
1202	        primary_bus = pcie_dev_info_chain->prev_pcie_info->config.primary_bus;
1203	        tmp_pcie_dev_info = topo_find_pice_info_from_primary_bus(primary_bus);
1204	        if (tmp_pcie_dev_info != NULL) {
1205	            tmp_pcie_dev_info->prev_pcie_info = pcie_dev_info_chain->prev_pcie_info;
1206	            pcie_dev_info_chain->prev_pcie_info = tmp_pcie_dev_info;
1207	            pcie_dev_info_chain->pcie_size++;
1208	        } else {
1209	            break;
1210	        }
1211	    }
1212	
1213	    if (loop == max_loop - 1) {
1214	        gplog(LOG_ERR, "the loop exited due to reaching the maximum number of cycles. loop is %u", loop);
1215	        return NPU_ERR_CODE_INNER_ERR;
1216	    }
1217	
1218	    return NPU_OK;
1219	}
