1221	STATIC int topo_get_pcie_chain_by_card_id(int dev_id, struct topo_pcie_info *pcie_dev_info_chain)
1222	{
1223	    // dev_id说明：910_93传入phy_id再转换为card_id和device_id,其余芯片传入card_id
1224	    int card_id, device_id, ret;
1225	    struct dcmi_pcie_info_all topo_dcmi_pcie_info = {0};
1226	
1227	    pcie_dev_info_chain->pcie_size = 0;
1228	    if (dcmi_board_chip_type_is_ascend_910_93()) {
1229	        ret = dcmi_get_card_id_device_id_from_phyid(&card_id, &device_id, (unsigned int)dev_id);
1230	        if (ret != DCMI_OK) {
1231	            gplog(LOG_ERR, "Get card id and device id failed. (ret=[%d]; phyid=[%d])", ret, dev_id);
1232	            return ret;
1233	        }
1234	        ret = dcmi_get_device_pcie_info_v2(card_id, device_id, &topo_dcmi_pcie_info);
1235	    } else {
1236	        // 非910_93中npu的device_id默认为0
1237	#ifndef NPU_SMI_V2
1238	        ret = dcmi_get_device_pcie_info_v2(dev_id, 0, &topo_dcmi_pcie_info);
1239	#else
1240	        ret = dcmiv2_get_device_pcie_info(dev_id, &topo_dcmi_pcie_info);
1241	#endif
1242	    }
1243	    if (ret != DCMI_OK) {
1244	        gplog(LOG_ERR, "dcmi_get_device_pcie_info_v2 failed. ret is %d", ret);
1245	        return ret;
1246	    }
1247	
1248	    topo_pcie_id_assignment(&topo_dcmi_pcie_info, pcie_dev_info_chain);
1249	
1250	    ret = topo_get_pcie_cfg_info_by_pcie_id(&pcie_dev_info_chain->pcie_id, &pcie_dev_info_chain->config);
1251	    if (ret != NPU_OK) {
1252	        gplog(LOG_ERR, "failed to get pcie cfg info by pcie id. ret is %d", ret);
1253	        return ret;
1254	    }
1255	
1256	    ret = topo_get_numa_node_by_pcie_id(&pcie_dev_info_chain->pcie_id, pcie_dev_info_chain);
1257	    if (ret != NPU_OK) {
1258	        gplog(LOG_ERR, "failed to get numa node by pcie id. ret is %d", ret);
1259	        return ret;
1260	    }
1261	
1262	    ret = topo_get_pcie_affinity_cpu_info_by_device_id(pcie_dev_info_chain->numa_node,
1263	        pcie_dev_info_chain->affinity_cpu);
1264	    if (ret != NPU_OK) {
1265	        gplog(LOG_ERR, "failed to get pcie affinity cpu info by device id. ret is %d", ret);
1266	        return ret;
1267	    }
1268	
1269	    pcie_dev_info_chain->pcie_size++;
1270	    pcie_dev_info_chain->prev_pcie_info = pcie_dev_info_chain;
1271	    pcie_dev_info_chain->next_pcie_info = pcie_dev_info_chain;
1272	
1273	    // 获取完整链路
1274	    ret = topo_get_full_pcie_chain(pcie_dev_info_chain);
1275	    if (ret != NPU_OK) {
1276	        gplog(LOG_ERR, "failed to get full pcie chain. ret is %d", ret);
1277	        return ret;
1278	    }
1279	
1280	    return NPU_OK;
1281	}
