1366	        (topo_operate_info->device_id_list[col] < TYPE_910_SERVER)) ||
1367	        ((topo_operate_info->device_id_list[row] >= TYPE_910_SERVER) &&
1368	        (topo_operate_info->device_id_list[col] >= TYPE_910_SERVER))) {
