1375	STATIC void query_topo_type(int row, int col, struct topo_pcie_info *pcie_info, struct topo_info *topo_operate_info)
1376	{
1377	    int work_mode = 0;
1378	    struct topo_pcie_info *root_dev_info_a = NULL;
1379	    struct topo_pcie_info *root_dev_info_b = NULL;
1380	
1381	    if (topo_is_same_pci_device(&pcie_info[row], &pcie_info[col])) {
1382	        topo_operate_info->topo_type_matrix[row][col] = TOPO_TYPE_SELF;
1383	        return;
1384	    }
1385	
1386	    if (pcie_info[row].numa_node != pcie_info[col].numa_node) {
1387	        if (npu_board_type_is_server()) {
1388	            (void)dcmi_get_npu_work_mode(0, (unsigned char*)&work_mode);
1389	            if (work_mode == NPU_SMP_WORK_MODE) {
1390	                query_topo_type_1980_server(row, col, topo_operate_info);
1391	                return;
1392	            }
1393	        }
1394	        topo_operate_info->topo_type_matrix[row][col] = TOPO_TYPE_SYS;
1395	        return;
1396	    }
1397	
1398	    root_dev_info_a = pcie_info[row].prev_pcie_info;
1399	    root_dev_info_b = pcie_info[col].prev_pcie_info;
1400	
1401	    if (strcmp(root_dev_info_a->local_cpu_list, root_dev_info_b->local_cpu_list) == 0) {
1402	        topo_operate_info->topo_type_matrix[row][col] = TOPO_TYPE_PHB;
1403	    } else {
1404	        topo_operate_info->topo_type_matrix[row][col] = TOPO_TYPE_BUTT;
1405	    }
1406	}
