1430	STATIC int match_ens_pattern(const char *str)
1431	{
1432	    // 空指针检查
1433	    if (str == NULL) {
1434	        return -1;
1435	    }
1436	
1437	    regex_t regex;
1438	    regmatch_t matches[2];  // 0是整个匹配，1是第一个捕获组
1439	    int ret;
1440	    char pattern[] = "^ens([0-9]).*";  // 使用捕获组获取数字
1441	    
1442	    // 编译正则表达式
1443	    ret = regcomp(&regex, pattern, REG_EXTENDED);
1444	    if (ret) {
1445	        fprintf(stderr, "无法编译正则表达式\n");
1446	        return -1;
1447	    }
1448	    
1449	    // 执行匹配
1450	    ret = regexec(&regex, str, REGEX_MATCH_NUM, matches, 0);
1451	    if (ret == 0) {
1452	        // 成功匹配，提取捕获组中的数字
1453	        if (matches[1].rm_so != -1) {  // 确保捕获组匹配成功
1454	            char num_str[2] = {0};
1455	            ret = strncpy_s(num_str, sizeof(num_str), str + matches[1].rm_so,
1456	                matches[1].rm_eo - matches[1].rm_so);
1457	            if (ret != 0) {
1458	                regfree(&regex);
1459	                return -1;
1460	            }
1461	            int num = atoi(num_str);
1462	            regfree(&regex);
1463	            return num;
1464	        }
1465	    }
1466	    
1467	    regfree(&regex);
1468	    return -1;  // 匹配失败
1469	}
