1471	STATIC void find_interfaces(char interfaces[][NIC_NAME_LEN])
1472	{
1473	    FILE *fp;
1474	    char buffer[1024]; // 设置较大的1024以接收网卡信息
1475	    char tempInterfaces[NIC_NAME_LEN];
1476	    int ret;
1477	
1478	    ret = memset_s(interfaces, NIC_PORT_NUM * NIC_NAME_LEN, 0, NIC_PORT_NUM * NIC_NAME_LEN);
1479	    if (ret != 0) {
1480	        return;
1481	    }
1482	
1483	    // 执行命令并读取输出
1484	    fp = popen("ifconfig | grep 'flags'", "r");
1485	    if (fp == NULL) {
1486	        gplog(LOG_ERR, "Failed to run command");
1487	        return;
1488	    }
1489	    // 读取输出并处理
1490	    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
1491	        char *colon_pos = strchr(buffer, ':');
1492	
1493	        if (colon_pos == NULL) {
1494	            continue;
1495	        }
1496	
1497	        // 计算网卡名称长度
1498	        size_t name_len = colon_pos - buffer;
1499	        if (name_len >= NIC_NAME_LEN) {
1500	            name_len = NIC_NAME_LEN - 1;
1501	        }
1502	
1503	        ret = strncpy_s(tempInterfaces, sizeof(tempInterfaces), buffer, name_len);
1504	        if (ret != 0) {
1505	            continue;
1506	        }
1507	        tempInterfaces[name_len] = '\0';  // 确保字符串终止
1508	
1509	        int num = match_ens_pattern(tempInterfaces);
1510	        if (num != -1 && num < NIC_PORT_NUM) {
1511	            // 复制网卡名称到数组
1512	            ret = strncpy_s(interfaces[num], NIC_NAME_LEN, tempInterfaces, name_len);
1513	            if (ret != 0) {
1514	                continue;
1515	            }
1516	            interfaces[num][name_len] = '\0';  // 确保字符串终止
1517	        }
1518	    }
1519	
1520	    // 关闭管道
1521	    pclose(fp);
1522	}
