1524	STATIC void set_nic_npu_topo(struct topo_info *topo_operate_info, int nic_idx)
1525	{
1526	    int col;
1527	    for (col = 0; col < NIC_NPU_RATIO; col++) {
1528	        int npu_idx = nic_idx * NIC_NPU_RATIO + col;
1529	        if (npu_idx < topo_operate_info->device_count) {
1530	            topo_operate_info->nic_topo_matrix[nic_idx][npu_idx] = TOPO_TYPE_UB;
1531	        }
1532	    }
1533	}
