1535	STATIC void npu_nic_topo_matrix(struct topo_info *topo_operate_info)
1536	{
1537	    // 空指针检查
1538	    if (topo_operate_info == NULL) {
1539	        gplog(LOG_ERR, "topo_operate_info is NULL");
1540	        return;
1541	    }
1542	
1543	    int col, ret, nic_idx;
1544	    char interfaces[NIC_PORT_NUM][NIC_NAME_LEN] = {0};
1545	
1546	    // 初始化 NIC 拓扑矩阵为 NA (TOPO_TYPE_BUTT)
1547	    for (nic_idx = 0; nic_idx < NIC_PORT_NUM; nic_idx++) {
1548	        for (col = 0; col < topo_operate_info->device_count; col++) {
1549	            topo_operate_info->nic_topo_matrix[nic_idx][col] = TOPO_TYPE_BUTT;
1550	        }
1551	        // 初始化 NIC 名称为空
1552	        ret = memset_s(topo_operate_info->nic_name_list[nic_idx], NIC_NAME_LEN, 0, NIC_NAME_LEN);
1553	        if (ret != 0) {
1554	            return;
1555	        }
1556	    }
1557	
1558	    // 查找网卡信息
1559	    find_interfaces(interfaces);
1560	
1561	    // 填充 NIC 拓扑矩阵：NIC与NPU按顺序1对NIC_NPU_RATIO对应
1562	    // NIC0 -> NPU0-3, NIC1 -> NPU4-7, NIC2 -> NPU8-11, NIC3 -> NPU12-15
1563	    for (nic_idx = 0; nic_idx < NIC_PORT_NUM; nic_idx++) {
1564	        if (interfaces[nic_idx][0] == '\0') {
1565	            continue;
1566	        }
1567	        // 网卡存在，复制名称并设置为 UB
1568	        ret = strncpy_s(topo_operate_info->nic_name_list[nic_idx], NIC_NAME_LEN,
1569	            interfaces[nic_idx], NIC_NAME_LEN - 1);
1570	        if (ret != 0) {
1571	            continue;
1572	        }
1573	        topo_operate_info->nic_name_list[nic_idx][NIC_NAME_LEN - 1] = '\0';
1574	
1575	        // 设置对应的NIC_NPU_RATIO个NPU为UB
1576	        set_nic_npu_topo(topo_operate_info, nic_idx);
1577	    }
1578	
1579	    return;
1580	}
