1657	STATIC int query_topo_permission_check()
1658	{
1659	    int ret = 0;
1660	    unsigned int env_flag = ENV_PHYSICAL;
1661	
1662	    // 定义一个函数指针数组，元素是需要检查的规则函数
1663	    int (*const rule_functions[3])(unsigned int) = {
1664	        rule_x86_vm_unsupported,
1665	        rule_arm_vm_unsupported,
1666	        rule_vm_container
1667	    };
1668	    const size_t num_rules = sizeof(rule_functions) / sizeof(rule_functions[0]);
1669	
1670	    // 虚拟机容器场景不支持
1671	    ret = dcmi_get_environment_flag(&env_flag);
1672	    if (ret != DCMI_OK) {
1673	        gplog(LOG_ERR, "call dcmi_get_environment_flag failed. err is %d.", ret);
1674	        return ret;
1675	    }
1676	
1677	    // 遍历所有规则函数
1678	    for (size_t i = 0; i < num_rules; ++i) {
1679	        ret = rule_functions[i](env_flag);
1680	        if (ret != DCMI_OK) {
1681	            return ret;
1682	        }
1683	    }
1684	    
1685	    // 仅910A2、910A3、910A5支持x86
1686	    if (!(dcmi_board_chip_type_is_ascend_910b() || dcmi_board_chip_type_is_ascend_910_93() ||
1687	        dcmi_board_chip_type_is_ascend_950())) {
1688	        if (!dcmi_is_arm()) {
1689	            gplog(LOG_ERR, "this api is not support x86");
1690	            return NPU_ERR_CODE_NOT_SUPPORT;
1691	        }
1692	    }
1693	 
1694	    return DCMI_OK;
1695	}
