1831	STATIC int show_ascend_sys_log_info(struct npu_smi_operate_info *operate_info)
1832	{
1833	    int ret, gear, card_num, persistence_enable = 0;
1834	    int card_id_list[MAX_CARD_NUM] = {0};
1835	    int logic_id_list[MAX_CARD_NUM] = {0};
1836	    int card_msn_existed[MAX_CARD_NUM] = {0}; // 有日志落盘持久化进程的card id列表
1837	    char cfg[SYS_LOG_MAX_CMD_LINE] = {0};
