1839	 
1840	    ret = memset_s(card_msn_existed, sizeof(card_msn_existed), -1, sizeof(card_msn_existed));
1841	    if (ret != NPU_OK) {
1842	        gplog(LOG_ERR, "Call memset_s failed. err is %d", ret);
1843	        return NPU_ERR_CODE_INNER_ERR;
1844	    }
1845	
1846	    if (operate_info->has_id) {
1847	        printf("This command does not support input card id.\n");
1848	        return NPU_ERR_CODE_INVALID_PARAMETER;
1849	    }
1850	
1851	    ret = get_card_and_logic_id_list(card_id_list, logic_id_list, &card_num);
1852	    if (ret != NPU_OK) {
1853	        printf("Get card id list or logic id list failed. ret = %d.\n", ret);
