1855	    }
1856	
1857	    ret = get_card_msn_existed_list(card_num, logic_id_list, card_id_list, card_msn_existed);
1858	    if (ret != NPU_OK) {
1859	        gplog(LOG_ERR, "get_card_msn_existed_list failed, ret = %d.", ret);
1860	        return dcmi_to_npu_error_code(ret);
1861	    }
1862	
1863	    ret = dcmi_get_syslog_persistence_info(&persistence_enable, cfg, sizeof(cfg) / sizeof(char));
1864	    if (ret == DCMI_ERR_CODE_CONFIG_INFO_NOT_EXIST) {
1865	        goto SYSLOG_DUMP_INFO;
1866	    } else if (ret == DCMI_ERR_CODE_SYSLOG_CONFIG_ILLEGAL) {
1867	        printf("ERROR: The configuration file has been maliciously modified, "
1868	                "please clear configuration and stop syslog collecting process first.\n");
1869	        return NPU_ERR_CODE_INNER_ERR;
1870	    } else if (ret != DCMI_OK) {
1871	        printf("Failed to show syslog dump mode.\n");
1872	        return dcmi_to_npu_error_code(ret);
1873	    }
1874	
1875	    if (cfg[0] != '\0') {
1876	        ret = sscanf_s(cfg, "/usr/local/bin/npu-smi set -t sys-log-dump -s %d -f %s", &gear, path, sizeof(path));
1877	        if (ret < 1) {  /* 解析失败 */
1878	            gplog(LOG_ERR, "sscanf_s failed. ret is %d", ret);
1879	            return NPU_ERR_CODE_INNER_ERR;
1880	        }
1881	    }
