394	    int i;
395	    unsigned int board_type = BOARD_TYPE_EP;
396	    const char *host_dev_path_ep[] = {DEV_HISI_HDC_PATH, DEV_DAVINCI_MANAGER_PATH, DEV_DEVMMM_SVM_PATH};
