585	static int read_shadow_password(struct password *passwd)
586	{
587	    int ret;
588	    int clr_ret;
589	    FILE *fp = NULL;
590	    char line_buf[MAX_LINE_SIZE] = {0};
591	
592	    fp = fopen(PASSWD_FILE_PATH, "r");
593	    if (fp == NULL) {
594	        DEV_MON_ERR("Open file failed.\n");
595	        return DRV_ERROR_OPER_NOT_PERMITTED;
596	    }
597	
598	    while (fgets(line_buf, MAX_LINE_SIZE, fp) != NULL) {
599	        if (strstr(line_buf, passwd->user_name)) {
600	            ret = sscanf_s(line_buf, "%[^:]:$%d$%[^:]\n",
601	                passwd->user_name, MAX_NAME_LEN, &(passwd->crypt_type), passwd->encrypted_passwd, MAX_PASSWD_LEN);
602	            if (ret != SSCANF_NUM || passwd->crypt_type != CRYPT_SHA512) {
603	                DEV_MON_ERR("Analysys passwd failed. (scanf_num=%d, crypt_type=%d)\n", ret, passwd->crypt_type);
604	                ret = COMMON_ERR;
605	                goto OUT;
606	            }
607	            ret = 0;
608	            goto OUT;
609	        }
610	    }
611	
612	    ret = COMMON_ERR;
613	    DEV_MON_ERR("Can not find user password. (user=\"%s\")\n", passwd->user_name);
614	
615	OUT:
616	    fclose(fp);
617	    fp = NULL;
618	    clr_ret = memset_s(line_buf, MAX_LINE_SIZE, 0, MAX_LINE_SIZE);
619	    if (clr_ret) {
620	        DEV_MON_ERR("Memset_s passwd line buf failed. (clr_ret=%d)", clr_ret);
621	    }
622	    return ret;
623	}
