625	STATIC int check_para_recovery_mode_passwd(unsigned char *buff, unsigned int buff_size)
626	{
627	    int ret;
628	    int clr_ret;
629	    struct password user_passwd = {{USER_NAME}, 0, {0}};
630	    struct password root_passwd = {{ROOT_NAME}, 0, {0}};
631	    unsigned int passwd_size = sizeof(struct password);
632	
633	    if (buff_size < (passwd_size + passwd_size)) {
634	        DEV_MON_ERR("Check para failed. (buf_size=%u)", buff_size);
635	        return DRV_ERROR_PARA_ERROR;
636	    }
637	
638	    ret = memset_s(buff, buff_size, 0, buff_size);
639	    if (ret) {
640	        DEV_MON_ERR("Memset_s buf failed. (ret=%d; buf_size=%u)", ret, buff_size);
641	        return ret;
642	    }
643	    ret = read_shadow_password(&user_passwd);
644	    if (ret) {
645	        DEV_MON_ERR("Read user passwdord form shadow failed. (ret=%d)\n", ret);
646	        goto OUT;
647	    }
648	
649	    ret = memcpy_s(buff, buff_size, &user_passwd, passwd_size);
650	    if (ret) {
651	        DEV_MON_ERR("Memcpy_s user passwd failed. (ret=%d)\n", ret);
652	        goto OUT;
653	    }
654	
655	    ret = read_shadow_password(&root_passwd);
656	    if (ret) {
657	        (void)memset_s(buff, buff_size, 0, buff_size);
658	        DEV_MON_ERR("Read root passwdord form shadow failed. (ret=%d)\n", ret);
659	        goto OUT;
660	    }
661	
662	    ret = memcpy_s(buff + passwd_size, buff_size - passwd_size, &root_passwd, passwd_size);
663	    if (ret) {
664	        (void)memset_s(buff, buff_size, 0, buff_size);
665	        DEV_MON_ERR("Memcpy_s root passwd failed. (ret=%d)\n", ret);
666	        goto OUT;
667	    }
668	
669	OUT:
670	    clr_ret = memset_s(&user_passwd, passwd_size, 0, passwd_size);
671	    if (clr_ret) {
