698	STATIC int check_user_cfg_para(int device_id, const char *config_name, unsigned int config_cmd, unsigned int *cfg_index)
699	{
700	    unsigned int i;
701	    unsigned int config_name_len;
702	
703	    if ((device_id < 0) || (device_id >= DEVDRV_MAX_DAVINCI_NUM) || (config_name == NULL)) {
704	        DEV_MON_ERR("Input para is error. (device_id=%d; config_name=%d)\n", device_id, (int)(config_name == NULL));
705	        return DRV_ERROR_PARA_ERROR;
706	    }
707	
708	    config_name_len = (unsigned int)strlen(config_name) + 1;
709	    if (config_name_len > DSMI_USER_CONFIG_NAME_MAX) {
710	        DEV_MON_ERR("Config name length is error. (device_id=%d; len=%u)\n", device_id, config_name_len);
711	        return DRV_ERROR_PARA_ERROR;
712	    }
713	    for (i = 0; i < UC_PROD_ITEM_MAX_NUM; i++) {
714	        if (strncmp(g_user_config_info_product[i].name, config_name, config_name_len) == 0) {
715	            break;
716	        }
717	    }
718	    if (i >= UC_PROD_ITEM_MAX_NUM) {
719	        DEV_MON_ERR("Can not find user config name in user_config_info. (config_name=\"%s\")\n", config_name);
720	        return DRV_ERROR_PARA_ERROR;
721	    }
722	
723	    if ((g_user_config_info_product[i].support_flag & (1U << config_cmd)) == 0) {
724	        DEV_MON_ERR("Config not support the cmd. (config_name=\"%s\"; cfg_index=%d; cmd_index=%u; support_flag=%u)\n",
725	            config_name, i, config_cmd, g_user_config_info_product[i].support_flag);
726	        return DRV_ERROR_NOT_SUPPORT;
727	    }
728	    *cfg_index = i;
729	
730	    return 0;
731	}
