1181	    unsigned char module_type, struct dsmi_ecc_common_data *ecc_common_data_s)
1182	{
1183	#if defined CFG_SOC_PLATFORM_CLOUD || defined CFG_FEATURE_ECC_DDR || defined CFG_SOC_PLATFORM_CLOUD_V4
1184	    int ret;
1185	    unsigned int data_index = 0;
1186	    unsigned int record_count = 0;
1187	    struct dsmi_ecc_pages_stru pdevice_ecc_pages_statistics = {0};
1188	    struct dsmi_multi_ecc_time_data multi_ecc_time_data = {0};
1189	
1190	    if ((module_type != DSMI_DEVICE_TYPE_HBM) && (module_type != DSMI_DEVICE_TYPE_DDR)) {
1191	        DEV_MON_ERR("moduletype %d is not supported\n", module_type);
1192	        return DRV_ERROR_NOT_SUPPORT;
1193	    }
1194	
1195	    if (ecc_common_data_s == NULL || ecc_count == NULL) {
1196	        DEV_MON_ERR("devid %d dsmi_get_multi_ecc_record_info parameter error!\n", device_id);
1197	        return DRV_ERROR_PARA_ERROR;
1198	    }
1199	
1200	    if (read_type == SINGLE_ECC_INFO_READ) {
1201	        ret = dsmi_cmd_get_total_ecc_isolated_pages_info(device_id, DSMI_HBM_RECORDED_SINGLE_ADDR,
1202	            &pdevice_ecc_pages_statistics);
1203	        if (ret) {
1204	            DEV_MON_ERR("devid %d dsmi_cmd_get_total_ecc_isolated_pages_info call error ret = %d!\n", device_id, ret);
1205	            return ret;
1206	        }
1207	        *ecc_count = pdevice_ecc_pages_statistics.corrected_ecc_errors_aggregate_total;
1208	    }
1209	
1210	    if (read_type == MULTI_ECC_INFO_READ) {
1211	        ret = dsmi_cmd_get_multi_ecc_time_info(device_id, &multi_ecc_time_data);
1212	        if (ret) {
