1214	            return ret;
1215	        }
1216	        *ecc_count = multi_ecc_time_data.multi_record_count;
1217	    }
1218	
1219	    record_count = (*ecc_count) > MAX_RECORD_ECC_ADDR_COUNT ? MAX_RECORD_ECC_ADDR_COUNT : (*ecc_count);
1220	    for (data_index = 0; data_index < record_count; data_index++) {
1221	        ret = dsmi_cmd_get_multi_ecc_record_info(device_id, (int)data_index, read_type, module_type,
1222	            &ecc_common_data_s[data_index]);
1223	        if (ret) {
1224	            DEV_MON_ERR("devid %d dsmi_cmd_get_multi_ecc_record_info call error ret = %d!\n", device_id, ret);
1225	            return ret;
1226	        }
1227	    }
1228	
1229	    return DRV_ERROR_NONE;
1230	#else
1231	    DEV_MON_ERR("Dsmi get multi ecc record info not support.\n");
1232	    return DRV_ERROR_NOT_SUPPORT;
1233	#endif
1234	}
